/* The home page is a launchpad into existing lessons; progress remains in the existing stores. */
function dashboardProgress(l){return l==='N5'?Math.round(Object.values(state.course.units).reduce((n,u)=>n+u.done.length,0)/(24*6)*100):counts(l).pct;}
function dashboardIcon(name){const paths={arrow:'M5 12h14m-6-6 6 6-6 6',book:'M4 4h6l2 2 2-2h6v15h-6l-2 2-2-2H4V4zm8 2v15',sound:'M4 10h4l5-4v12l-5-4H4v-4zm12-2c3 2 3 6 0 8m3-11c5 4 5 10 0 14',refresh:'M19 7a8 8 0 1 0 1 8M19 3v5h-5',check:'m5 12 4 4L19 6'};return `<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.arrow}"/></svg>`;}
renderHome=function(){
 const day=studyDay(),active=day.steps.findIndex(t=>!t.done),done=day.steps.filter(t=>t.done).length,all=active<0;
 const foundation=day.level==='N5'&&day.foundation<foundationTotal;
 const currentTitle=all?'今日任务已完成':foundation?foundationLesson(day.foundation).title:stepInfo(day.steps[active],day).title;
 const c=counts(level),due=dueWords().length,mistakes=Object.keys(state.mistakes).filter(id=>questionById(id)?.level===level).length;
 const resumeUnit=level==='N5'?(n5Unit(state.course.cursor?.unit)||n5NextUnit()):null;
 const resumeTitle=state.activeQuiz?'未完成的阶段练习':level==='N5'?(foundation?'五十音与发音':resumeUnit.title):nextGrammar(level).title;
 const resumeAttrs=state.activeQuiz?'data-page="practice"':level==='N5'?(foundation?`data-home-step="${Math.max(0,active)}"`:`data-n5unit="${resumeUnit.id}" data-openstage="${state.course.cursor?.unit===resumeUnit.id?state.course.cursor.stage:N5_STAGES.find(k=>!n5UnitState(resumeUnit.id).done.includes(k))||'review'}"`):`data-lesson="${nextGrammar(level).id}"`;
 const next=n5NextUnit(),start=Math.min(N5_UNITS.indexOf(next),21),units=N5_UNITS.slice(start,start+3);
 return `<div class="dashboard-shell"><section class="container dash-welcome"><div><span class="dash-date">${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</span><h1>把日语，学进每一天。</h1></div><button class="dash-archive" data-page="progress">${state.days.length} 天学习记录 ${dashboardIcon('arrow')}</button></section>
 <section class="container dash-top"><article class="dash-continue"><div class="dash-kicker"><span class="dash-dot"></span>继续学习 <span class="dash-pill">${state.activeQuiz?.level||level}</span></div><h2>${esc(resumeTitle)}</h2><p>${state.activeQuiz?'上次的答案已保存，可以接着作答。':foundation?'从一组假名开始，跟读、认读，再回忆。':level==='N5'?`第 ${N5_UNITS.indexOf(resumeUnit)+1} 单元 · ${N5_STAGE_NAMES[state.course.cursor?.unit===resumeUnit.id?state.course.cursor.stage:N5_STAGES.find(k=>!n5UnitState(resumeUnit.id).done.includes(k))||'review']}`:'理解句型，再通过例句与练习巩固。'}</p><button class="primary dash-resume" ${resumeAttrs}>${state.activeQuiz?'继续作答':'继续学习'} ${dashboardIcon('arrow')}</button><div class="dash-progress-info"><span>${level==='N5'?'单元步骤':'核心练习'}进度</span><strong>${dashboardProgress(level)}%</strong></div><div class="dash-track" role="progressbar" aria-label="${level}学习进度" aria-valuenow="${dashboardProgress(level)}" aria-valuemin="0" aria-valuemax="100"><i style="width:${dashboardProgress(level)}%"></i></div><span class="dash-art" aria-hidden="true">あ</span></article>
 <aside class="dash-review"><div class="dash-card-head"><h2>温故知新</h2>${dashboardIcon('refresh')}</div><button class="dash-review-link" data-home-review ${!due?'disabled':''}><span><b>${due}</b> 个到期词汇</span><span>${due?'去复习':'已清空'} ${dashboardIcon('arrow')}</span></button><button class="dash-review-link" data-home-mistakes ${!mistakes?'disabled':''}><span><b>${mistakes}</b> 道待巩固错题</span><span>${mistakes?'去巩固':'暂无错题'} ${dashboardIcon('arrow')}</span></button><div class="dash-skills"><button data-page="reading">${dashboardIcon('book')}阅读</button><button data-page="listening">${dashboardIcon('sound')}听力</button></div></aside></section>
 <section class="container dash-today"><div class="dash-section-head"><div><h2>今日安排 <span>${done}/${day.steps.length}</span></h2><p>第 ${day.number} 学习日 · ${state.plan.minutes} 分钟</p></div><button data-page="plan">${all?'查看完成记录':'完整计划'} ${dashboardIcon('arrow')}</button></div><div class="dash-task-list">${day.steps.map((t,i)=>{const info=stepInfo(t,day);return `<button class="dash-task ${t.done?'is-done':i===active?'is-current':'is-pending'}" data-home-step="${i}" ${!all&&i>active?'disabled':''}><span class="dash-task-number">${t.done?dashboardIcon('check'):String(i+1).padStart(2,'0')}</span><span class="dash-task-copy"><span>${t.done?'已完成':i===active?'接下来学':'稍后学习'} · ${info.time}</span><strong>${esc(foundation?i===0?'跟读与认读':'回忆检查':day.n5Unit?N5_STAGE_NAMES[day.n5Stages[i]]:info.title)}</strong></span>${dashboardIcon('arrow')}</button>`;}).join('')}</div>${all?'<button class="primary dash-next-day" data-home-next>开始下一学习日 →</button>':''}</section>
 <section class="container dash-route"><div class="dash-section-head"><div><h2>我的学习路线</h2></div><button data-page="lessons">课程目录 ${dashboardIcon('arrow')}</button></div><div class="dash-levels" role="group" aria-label="选择路线等级">${LEVELS.map(l=>`<button data-home-level="${l}" aria-pressed="${l===level}" class="${l===level?'selected':''}"><strong>${l}</strong><span>${l==='N5'?'系统课程':'核心练习'}</span><span class="dash-level-progress">${dashboardProgress(l)}%</span></button>`).join('')}</div><div class="dash-route-content">${level==='N5'?`<div class="dash-course-meta"><span>24 个生活场景</span><span>已通过 ${n5Passed()} 个单元</span></div><div class="dash-unit-grid">${units.map(u=>{const st=n5UnitState(u.id);return `<button class="dash-unit" data-n5unit="${u.id}"><div><span>第 ${N5_UNITS.indexOf(u)+1} 单元</span><span class="dash-unit-status ${st.done.includes('review')?'passed':u.id===next.id?'current':''}">${st.done.includes('review')?'已通过':u.id===next.id?'继续学':'待学习'}</span></div><h3>${esc(u.title)}</h3><div class="dash-unit-bottom"><span>${st.done.length}/6 步骤</span>${dashboardIcon('arrow')}</div></button>`;}).join('')}</div>`:`<div class="dash-next-level"><div><h3>${levelInfo[level].name}</h3><p>语法 ${c.g}/${c.gt} · 阅读 ${c.r}/${c.rt} · 听力 ${c.l}/${c.lt}</p></div><button class="primary" data-page="lessons">进入 ${level} 课程 →</button></div>`}</div></section></div>`;
};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;
 if(d.homeLevel){go('home',d.homeLevel);}
 if(d.homeStep!==undefined){const day=studyDay(),i=Number(d.homeStep),active=day.steps.findIndex(t=>!t.done);if(!Number.isInteger(i)||!day.steps[i]||(active>=0&&i>active))return;go('plan',day.level);render(false);runStep(i);}
 if(d.homeReview!==undefined){guideActive=false;wordReviewMode='due';go('vocab',level);}
 if(d.homeMistakes!==undefined){guideActive=false;go('practice',level);render(false);startQuiz('review');}
 if(d.homeNext!==undefined){const day=syncStudyDay();if(day.steps.every(t=>t.done)){archiveDay();guideActive=false;persist();render(false);toast('下一学习日已准备好。');}}
});
render(false);
